import{_ as t,c as n,o as s,ah as i}from"./chunks/framework.BjIn8lrq.js";const u=JSON.parse('{"title":"34. Qualitätssicherung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-c-entwicklungs-systemdokumentation/34-qualitaetssicherung.md","filePath":"manual/teil-c-entwicklungs-systemdokumentation/34-qualitaetssicherung.md"}'),a={name:"manual/teil-c-entwicklungs-systemdokumentation/34-qualitaetssicherung.md"};function d(r,e,l,o,c,h){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="_34-qualitatssicherung" tabindex="-1">34. Qualitätssicherung <a class="header-anchor" href="#_34-qualitatssicherung" aria-label="Permalink to &quot;34. Qualitätssicherung&quot;">​</a></h1><p>Dieses Kapitel beschreibt die Tests, Prüfwerkzeuge und automatischen Abläufe des Repositorys: was es gibt, wie Sie es ausführen und was davon bei jedem Commit läuft.</p><table tabindex="0"><thead><tr><th>Ebene</th><th>Werkzeug</th><th>In der CI</th></tr></thead><tbody><tr><td>Backend</td><td>pytest mit pytest-django und factory_boy</td><td>nein</td></tr><tr><td>Frontend</td><td>Vitest</td><td>ja</td></tr><tr><td>End-to-End</td><td>Playwright</td><td>nur von Hand</td></tr><tr><td>Typen</td><td>svelte-check</td><td>ja</td></tr><tr><td>Formatierung und Linting</td><td>Prettier, ESLint, ruff</td><td>nein</td></tr></tbody></table><h2 id="_34-1-backend-tests" tabindex="-1">34.1 Backend-Tests <a class="header-anchor" href="#_34-1-backend-tests" aria-label="Permalink to &quot;34.1 Backend-Tests&quot;">​</a></h2><p>Die Tests des Backends liegen in <code>backend/apps/api/tests/</code>: Dateien <code>test_*.py</code> für Endpunkte, Dienste, Routing, Faserweg, Rechte, Signale und Validatoren, dazu die Unterordner <code>models/</code> und <code>viewsets/</code>. Testdaten erzeugen die Factories in <code>factories.py</code> (factory_boy); <code>conftest.py</code> stellt sie als Fixtures bereit, schaltet für jeden Test auf Englisch, damit Meldungen vergleichbar sind, und leert den Zwischenspeicher der Content Types.</p><p>Die Konfiguration steht in <code>pytest.ini</code> im <strong>Wurzelverzeichnis</strong> des Repositorys, nicht in <code>backend/</code>. pytest sucht sie vom Arbeitsverzeichnis aus nach oben und findet sie auch aus <code>backend/</code> heraus; dort greift zusätzlich die Einstellung der Abdeckung aus <code>backend/pyproject.toml</code>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Die Tests brauchen eine echte PostgreSQL-Datenbank mit PostGIS; eine SQLite-Datenbank genügt nicht, weil Geometrien, Trigger und <code>pg_trgm</code> im Spiel sind. Die Verbindung kommt wie beim Entwicklungsserver aus <code>deployment/.env</code> und der Shell, siehe Abschnitt <a href="./30-entwicklungsumgebung.html#_30-2-backend-starten">Backend starten</a>. pytest-django legt daneben eine Testdatenbank <code>test_&lt;DB_NAME&gt;</code> an; das Konto aus <code>DB_USER</code> braucht dafür das Recht, Datenbanken anzulegen. Der Container aus Abschnitt <a href="./30-entwicklungsumgebung.html#_30-2-backend-starten">Backend starten</a> legt <code>POSTGRES_USER</code> als Superuser an und erfüllt das.</p><p>Der Lauf, aus dem die Zahl in der Tabelle oben stammt, nutzte die Python-Pakete des Backend-Images, nicht die aus <code>uv.lock</code>, siehe Abschnitt <a href="./29-architekturueberblick.html#_29-2-technologiestack">Technologiestack</a>.</p><p><code>--reuse-db</code> steht in den Voreinstellungen: Die Testdatenbank bleibt zwischen zwei Läufen bestehen, und ein Lauf beginnt ohne erneute Migration. Nach einer neuen Migration rufen Sie pytest einmal mit <code>--create-db</code> auf, sonst laufen die Tests gegen den alten Stand der Tabellen.</p><p><code>pytest.ini</code> deklariert neben <code>django_db</code> von pytest-django die Marker <code>slow</code>, <code>integration</code> und <code>unit</code>, kein Test setzt sie aber; <code>-m integration</code> wählt deshalb nichts aus. Teile wählen Sie über den Pfad oder mit <code>-k</code>. <code>--strict-markers</code> lässt außer den eingebauten Markern von pytest keine anderen als die deklarierten zu. Die Abdeckung misst pytest-cov, eingestellt in <code>backend/pyproject.toml</code> (<code>[tool.coverage.*]</code>): <code>uv run pytest --cov</code> in <code>backend/</code>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p><code>backend/README.md</code> nennt Testdateien, die es nicht mehr gibt (<code>test_models.py</code>). Maßgeblich ist der Inhalt von <code>backend/apps/api/tests/</code>.</p></div><h2 id="_34-2-frontend-tests" tabindex="-1">34.2 Frontend-Tests <a class="header-anchor" href="#_34-2-frontend-tests" aria-label="Permalink to &quot;34.2 Frontend-Tests&quot;">​</a></h2><p>Die Tests des Frontends führt Vitest aus, eingestellt in <code>frontend/vite.config.ts</code> mit zwei Projekten:</p><ul><li><strong><code>client</code></strong> – Komponenten und Zustandsklassen, Dateien <code>*.svelte.test.ts</code>, in jsdom mit der Testing Library für Svelte. <code>vitest-setup-client.js</code> ersetzt dort alle Remote Functions (<code>*.remote</code>), <code>ResizeObserver</code> und <code>matchMedia</code> durch Attrappen.</li><li><strong><code>server</code></strong> – Lade-Funktionen, Formularaktionen und Hilfsfunktionen, Dateien <code>*.test.ts</code>, in Node.</li></ul><p>Die Tests liegen neben dem Code, den sie prüfen. Gemeinsame Attrappen stehen in <code>src/lib/test-utils/</code>, darunter eine für Svelte Flow und eine für die Karte; einige Komponenten haben für ihre Tests eine Hülle <code>*.fixture.svelte</code>.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # alle Tests einmal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:unit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # im Beobachtungsmodus</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:coverage</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # mit Abdeckung, Bericht in coverage/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Die Tests brauchen weder Backend noch Datenbank. In der CI laufen sie mit <code>TZ=Europe/Berlin</code>; Tests mit Datumsangaben können in einer anderen Zeitzone abweichen. Setzen Sie die Variable lokal ebenso, wenn ein solcher Test nur bei Ihnen scheitert.</p><h2 id="_34-3-end-to-end-tests" tabindex="-1">34.3 End-to-End-Tests <a class="header-anchor" href="#_34-3-end-to-end-tests" aria-label="Permalink to &quot;34.3 End-to-End-Tests&quot;">​</a></h2><p>Die End-to-End-Tests liegen in <code>frontend/tests/e2e/</code>, eine Datei je Bereich der Oberfläche, mit gemeinsamer Anmeldung in <code>helpers/auth.js</code>. <code>frontend/playwright.config.js</code> startet sie in Chromium, Firefox und WebKit gegen <code>http://localhost:5173</code> und ruft dafür selbst <code>npm run dev</code> auf, falls dort noch nichts läuft.</p><p>Die Tests klicken sich durch eine laufende Anwendung. Sie brauchen deshalb:</p><ul><li>ein laufendes Backend mit Daten, an das das Frontend über <code>.env</code> angeschlossen ist, siehe Kapitel <a href="./30-entwicklungsumgebung.html">Entwicklungsumgebung</a>,</li><li>ein Konto zum Anmelden, in <code>frontend/.env</code> als <code>E2E_TEST_USERNAME</code> und <code>E2E_TEST_PASSWORD</code>.</li></ul><p>Fehlen die Zugangsdaten oder schlägt die Anmeldung fehl, überspringen die Tests sich selbst, statt zu scheitern. Ein Lauf ohne Fehler sagt deshalb nur etwas, wenn der Bericht auch ausgeführte Tests zeigt.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with-deps</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # einmal: Browser installieren</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-report</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der Workflow „Playwright Tests“ in GitHub Actions startet nur von Hand und bringt weder Backend noch Zugangsdaten mit. Auf GitHub überspringen die Tests sich deshalb alle selbst; aussagekräftig ist nur ein lokaler Lauf gegen eine vollständige Umgebung.</p></div><h2 id="_34-4-linting-formatierung-und-typprufung" tabindex="-1">34.4 Linting, Formatierung und Typprüfung <a class="header-anchor" href="#_34-4-linting-formatierung-und-typprufung" aria-label="Permalink to &quot;34.4 Linting, Formatierung und Typprüfung&quot;">​</a></h2><p><strong>Frontend.</strong> Die Namen der Skripte in <code>frontend/package.json</code> führen teils in die Irre:</p><table tabindex="0"><thead><tr><th>Skript</th><th>Wirkung</th></tr></thead><tbody><tr><td><code>npm run check</code></td><td>übersetzt die Texte mit Paraglide, synchronisiert SvelteKit und prüft Typen mit svelte-check</td></tr><tr><td><code>npm run lint</code></td><td>prüft nur die Formatierung mit Prettier</td></tr><tr><td><code>npm run lint:ts</code></td><td>ESLint über <code>src/**/*.{ts,svelte}</code></td></tr><tr><td><code>npm run format</code></td><td>formatiert alles mit Prettier – zum Stand des Handbuchs auch fremde Dateien</td></tr></tbody></table><p>Prettier ist eingestellt in <code>.prettierrc</code>: Tabulatoren, einfache Anführungszeichen, 100 Zeichen, das Plugin für Svelte und eine feste Reihenfolge der Importe. ESLint (<code>eslint.config.js</code>) nutzt die empfohlenen Regeln für TypeScript und Svelte und verbietet vor allem <code>any</code>.</p><p><strong>Backend.</strong> Für Python gibt es nur ruff, ohne eigene Konfiguration, also mit seinen Voreinstellungen. Rufen Sie es über uv auf, damit die gesperrte Version läuft:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Typprüfung für Python (mypy o. ä.) und pre-commit-Hooks gibt es nicht.</p><p>Der bestehende Code ist nicht frei von Befunden: ESLint meldet Fehler, Prettier beanstandet Dateien, die Paraglide selbst in <code>project.inlang/</code> erzeugt, und <code>ruff format --check</code> würde Dateien im Backend anders formatieren. Keines dieser Werkzeuge läuft in der CI; ein neuer Befund fällt dort nicht auf. Prüfen Sie Ihre eigenen Änderungen deshalb vor dem Commit selbst, und formatieren Sie nur die geänderten Dateien – <code>npx prettier --write &lt;Datei&gt;</code>, <code>uv run ruff format &lt;Datei&gt;</code> –, damit der Diff nicht fremde Stellen umformatiert.</p><p>In VS Code formatiert <code>.vscode/settings.json</code> beim Speichern Python mit ruff, JavaScript mit Prettier und Svelte mit der Svelte-Erweiterung, sofern die Erweiterungen installiert sind; für TypeScript legt die Datei keinen Formatierer fest.</p><h2 id="_34-5-ci-pipeline" tabindex="-1">34.5 CI-Pipeline <a class="header-anchor" href="#_34-5-ci-pipeline" aria-label="Permalink to &quot;34.5 CI-Pipeline&quot;">​</a></h2><p>Die automatischen Abläufe liegen in <code>.github/workflows/</code>:</p><table tabindex="0"><thead><tr><th>Workflow</th><th>Auslöser</th><th>Wirkung</th></tr></thead><tbody><tr><td><code>frontend-ci.yml</code> („Frontend CI“)</td><td>Push und Pull Request auf <code>main</code></td><td><code>npm ci</code>, <code>npm run check</code>, prüft <code>api.d.ts</code>, <code>npm test</code></td></tr><tr><td><code>playwright.yml</code> („Playwright Tests“)</td><td>nur von Hand</td><td>End-to-End-Tests, Bericht als Artefakt, siehe Abschnitt <a href="#_34-3-end-to-end-tests">End-to-End-Tests</a></td></tr><tr><td><code>release-please.yml</code></td><td>Push auf <code>main</code></td><td>pflegt den Release-Pull-Request, siehe Abschnitt <a href="./36-erweitern-und-mitwirken.html#_36-4-beitragsprozess-versionierung-releases">Beitragsprozess, Versionierung, Releases</a></td></tr></tbody></table><p>Die CI des Frontends erzeugt <code>src/lib/types/api.d.ts</code> aus der eingecheckten <code>backend/schema.yml</code> neu und bricht ab, wenn sich die Datei dabei ändert. Damit fällt auf, wenn jemand das Schema erneuert, die Typen aber nicht; dass das Schema zum Code des Backends passt, prüft sie nicht, siehe Abschnitt <a href="./32-rest-api.html#_32-7-openapi-schema-und-typgenerierung">OpenAPI-Schema und Typgenerierung</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Für das Backend gibt es keine CI. Seine Tests, ruff und das Schema prüft niemand automatisch; ein Pull Request, der das Backend bricht, besteht die Prüfungen auf GitHub. Lassen Sie <code>pytest</code> vor jedem Pull Request, der das Backend berührt, selbst laufen.</p></div><p>Images baut keiner der Workflows; die Container entstehen auf dem Server, siehe Abschnitt <a href="./35-bereitstellung-und-infrastruktur.html#_35-2-container-und-images">Container und Images</a>.</p>`,40)])])}const k=t(a,[["render",d]]);export{u as __pageData,k as default};
